import sys

def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    pos = sorted(int(x) for x in data[2:2 + n])
    def ok(d):
        cnt, last = 1, pos[0]
        for p in pos:
            if p - last >= d:
                cnt += 1
                last = p
                if cnt >= m:
                    return True
        return cnt >= m
    lo, hi = 1, (pos[-1] - pos[0]) // (m - 1)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if ok(mid):
            lo = mid
        else:
            hi = mid - 1
    print(lo)

main()

