def gen(rng):
    def fmt(pos, m):
        return '%d %d\n%s' % (len(pos), m, ' '.join(map(str, pos)))
    tests = [fmt([1, 2], 2), fmt([1, 10**9], 2), fmt([5, 1, 3], 3), fmt([1, 2, 3, 4], 2), fmt([1, 2, 4, 8, 9], 3)]
    for n in (3, 4, 5, 6, 8, 10, 12):
        for _ in range(3):
            hi = rng.choice([n + 2, 30, 100])
            pos = rng.sample(range(1, hi + 1), n)
            tests.append(fmt(pos, rng.randint(2, n)))
    for n in (4, 7, 10):
        pos = rng.sample(range(1, 10**9 + 1), n)
        tests.append(fmt(pos, rng.randint(2, n)))
    N = 50000
    big = rng.sample(range(1, 10**9 + 1), N)
    tests.append(fmt(big, 2))
    tests.append(fmt(big, N))
    tests.append(fmt(big, 1000))
    tests.append(fmt(rng.sample(range(1, 10**9 + 1), N), 25000))
    return tests

